insert into public.products
  (id, title, category, badge, price, images, description, details, old_price, note, created_at)
values
  (md5('avogan-wax')::uuid, 'Avogan Wax', 'tissus', 'Populaire', 10000, array['img-tissus/avogan wax.jpg']::text[], 'Wax avogan célèbre pour ses motifs géométriques et ses couleurs éclatantes. Un tissage souple, d''un poids juste, qui en fait un tissu incontournable pour les boubous, les chemises et les tenues de fête.', array['100 % coton', 'Motifs traditionnels', 'Rouleau de 6 yards', 'Couleurs grand teint']::text[], null, 4.5, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('chigaviny-wax')::uuid, 'Chigaviny Wax', 'tissus', 'Nouveau', 12500, array['img-tissus/chigaviny wax.jpg']::text[], 'Wax chigaviny à l''esprit raffiné, dont les motifs dégradés et les touches dorées captent la lumière. Le tissu des occasions où l''élégance se remarque de loin.', array['Tissage serré', 'Fils dorés', 'Rouleau de 6 yards', 'Double face']::text[], 14000, 4.6, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('popelin-perle')::uuid, 'Popelin Perlé', 'tissus', null, 9500, array['img-tissus/popelin perlé.jpg']::text[], 'Popelin perlé, un tissu fin, léger et brillant, reconnaissable à son grain nacré. Idéal pour les robes légères, les chemises et les doublures de haute couture.', array['Texture perlée', 'Léger et fluide', 'Largeur 110 cm', '3 yards']::text[], null, 4.4, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('uniwax-top-gold')::uuid, 'Uniwax Top Gold', 'tissus', 'Premium', 13500, array['img-tissus/uniwax top gold.jpg']::text[], 'Uniwax top gold, un wax premium aux reflets dorés et à la tenue impeccable. Le choix des couturières et des boutiques pour les tenues de cérémonie.', array['Reflets dorés', 'Tenue impeccable', 'Rouleau de 6 yards', 'Qualité supérieure']::text[], 15000, 4.7, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('wax-choco-gold')::uuid, 'Wax Choco Gold', 'tissus', 'Cérémonie', 11000, array['img-tissus/wax choco gold.jpg']::text[], 'Wax choco gold aux tons chocolat et or, chaleureux et élégant. Un motif passe-partout qui convient aussi bien aux tenues du quotidien qu''aux occasions spéciales.', array['Tons chocolat et or', 'Motif complet', 'Rouleau de 6 yards', 'Lavable à la main']::text[], null, 4.5, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('wax-original-dogon')::uuid, 'Wax Original Dogon', 'tissus', 'Best-seller', 12000, array['img-tissus/wax original dogon.jpg']::text[], 'Wax original dogon, inspiré des motifs dogon : figures géométriques symboliques et couleurs profondes. Un tissu d''héritage qui se transmet de génération en génération.', array['Motifs dogon', 'Couleurs profondes', 'Rouleau de 6 yards', 'Tissage résistant']::text[], 13500, 4.8, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('wax-satin-perlage')::uuid, 'Wax Satin Perlage', 'tissus', 'Premium', 15000, array['img-tissus/wax satin perlage.jpg']::text[], 'Wax satin perlage, le plus demandé de notre sélection : un tissage satiné et un relief « perlage » qui attrape la lumière. Un rouleau de grande qualité pour vos tenues de grande occasion.', array['Tissage satiné perlage', 'Rouleau de 6 yards', 'Grands reflets dorés', 'Qualité supérieure']::text[], 17500, 4.9, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('wax-super-ankara')::uuid, 'Wax Super Ankara', 'tissus', 'Best-seller', 13000, array['img-tissus/wax super ankara.jpg']::text[], 'Wax super ankara, dense et résistant, avec de grands motifs ankara qui claquent à la lumière. Le tissu idéal pour les tenues du quotidien comme pour les grands événements.', array['Tissage serré et résistant', 'Grands motifs ankara', 'Rouleau de 6 yards', 'Belle tenue à la lumière']::text[], null, 4.6, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('woodin-bleu-royal-eclat-sauvage')::uuid, 'Woodin Bleu Royal - Eclat Sauvage', 'tissus', 'Premium', 14000, array['img-tissus/woodin bleu royal - eclat sauvage.jpg']::text[], 'Woodin bleu royal - éclat sauvage, un dégradé de bleu profond ponctué de touches vives. Un tissu moderne et raffiné qui met en valeur le port de la tenue.', array['Dégradé bleu royal', 'Motifs éclat sauvage', 'Rouleau de 6 yards', 'Finition satinée']::text[], 16000, 4.7, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('dentelles-et-voiles-brodes')::uuid, 'Dentelles et Voiles Brodés', 'tissus', 'Cérémonie', 13500, array['img-tissus-2/dentelles et voiles brodés.jpg']::text[], 'Dentelles et voiles brodés, des pièces légères et délicates pour voiler une tenue, encadrer un visage ou signer une robe de soirée. Le lace travaillé à la main fait toute la différence.', array['Lace brodé main', 'Très léger', '3 yards', 'Idéal voile et tenue']::text[], null, 4.7, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('eventails-de-wax-assortis')::uuid, 'Eventails de Wax Assortis', 'tissus', 'Nouveau', 12000, array['img-tissus-2/eventails de wax assortis.jpg']::text[], 'Eventails de wax assortis, plusieurs modèles aux motifs coordonnés avec nos rouleaux de wax. L''accessoire qui finalise une tenue de fête.', array['Modèles assortis', 'Manche en bois', 'Grande ouverture', 'Plusieurs coloris']::text[], null, 4.5, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('pagne-gtp-authentic-ghana')::uuid, 'Pagne GTP Authentic Ghana', 'tissus', 'Premium', 14000, array['img-tissus-2/pagne gtp authentic ghana.jpg']::text[], 'Pagne GTP Authentic Ghana, un pagne au tissage traditionnel ghanéen, épais et durable. La référence pour les boubous et les tenues traditionnelles d''exception.', array['Tissage traditionnel ghanéen', 'Épais et durable', 'Rouleau de 6 yards', 'Couleurs résistantes']::text[], null, 4.8, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('robes-batik-teints')::uuid, 'Robes Batik Teints', 'tissus', 'Premium', 18500, array['img-tissus-2/robes batik teints.jpg']::text[], 'Robes Batik Teints, des robes déjà prêtes à porter, teintées au batik et cousues main. La solution pour être habillée sans attendre la confection.', array['Teinté au batik', 'Cousu main', 'Tailles M à XL', 'Livraison en 48 h']::text[], 22000, 4.9, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('super-wax-neerlandais')::uuid, 'Super Wax Néerlandais', 'tissus', 'Best-seller', 12500, array['img-tissus-2/super wax néerlandais.jpg']::text[], 'Super Wax néerlandais, un wax aux motifs fins inspirés de la tradition néerlandaise, souple et facile à coudre. Très demandé pour les tenues chiques du quotidien.', array['Motifs fins', 'Souple et facile à coudre', 'Rouleau de 6 yards', 'Tenue des couleurs']::text[], 14000, 4.7, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('tissus-block-print-style')::uuid, 'Tissus Block Print Style', 'tissus', null, 10500, array['img-tissus-2/tissus block print style.jpg']::text[], 'Tissus Block Print Style, un imprimé obtenu par tampons de bois, artisanal et légèrement irrégulier. Un style naturel, très demandé pour les robes d''été.', array['Imprimé au tampon', 'Artisanal', 'Rouleau de 6 yards', 'Légèrement irrégulier']::text[], null, 4.5, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('wax-dentelle-haute-couture')::uuid, 'Wax Dentelle Haute Couture', 'tissus', 'Premium', 16000, array['img-tissus-2/wax dentelle haute couture.jpg']::text[], 'Wax Dentelle Haute Couture, l''alliance du wax et de la dentelle, un tissu de podium pour les occasions qui doivent laisser une trace.', array['Wax et dentelle', 'Tissage serré', 'Rouleau de 6 yards', 'Niveau couture']::text[], 18000, 4.9, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('wax-golden-edition-limitee')::uuid, 'Wax Golden Edition Limitée', 'tissus', 'Best-seller', 17000, array['img-tissus-2/wax golden edition limitée.jpg']::text[], 'Wax Golden Edition Limitée, une série limitée aux fils dorés, produite en petite quantité. Tant qu''il en reste, il n''y en aura pas deux pareils.', array['Série limitée', 'Fils dorés', 'Rouleau de 6 yards', 'Quantités limitées']::text[], null, 4.8, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('wax-haute-couture-graphique-et-abstrait')::uuid, 'Wax Haute Couture Graphique et Abstrait', 'tissus', 'Cérémonie', 15500, array['img-tissus-2/wax haute couture graphique et abstrait.jpg']::text[], 'Wax Haute Couture Graphique et Abstrait, des formes graphiques fortes qui modernisent la coupe. Le choix des créatrices pour les tenues de soirée qui doivent marquer les esprits.', array['Motifs graphiques', 'Tissage dense', 'Rouleau de 6 yards', 'Finition haut de gamme']::text[], 17500, 4.7, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('wax-imperial-dentelle')::uuid, 'Wax Imperial Dentelle', 'tissus', 'Premium', 15000, array['img-tissus-2/wax imperial dentelle.jpg']::text[], 'Wax Imperial Dentelle, un wax d''une densité rare orné de dentelle, lourd et somptueux. Un tissu de cérémonie, taillé pour les grands jours.', array['Densité rare', 'Dentelle intégrée', 'Rouleau de 6 yards', 'Tissage lourd']::text[], null, 4.7, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('wax-imprime-premium')::uuid, 'Wax Imprimé Premium', 'tissus', 'Nouveau', 11500, array['img-tissus-2/wax imprimé premium.jpg']::text[], 'Wax Imprimé Premium, un wax aux motifs bien définis, aux couleurs franches et à la finition soignée. Un classique qui se porte toute l''année.', array['Impression nette', 'Couleurs franches', 'Rouleau de 6 yards', 'Finition soignée']::text[], 13000, 4.6, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('wax-prestige-floral')::uuid, 'Wax Prestige Floral', 'tissus', 'Best-seller', 13000, array['img-tissus-2/wax prestige floral.jpg']::text[], 'Wax Prestige Floral, un imprimé floral raffiné où les fleurs s''enroulent sur un fond profond. Un tissu délicat qui met en valeur les tenues de cérémonie.', array['Imprimé floral', 'Fleurs sur fond profond', 'Rouleau de 6 yards', 'Teintes tramées']::text[], null, 4.8, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('wax-sika-imprimes-traditionnels')::uuid, 'Wax Sika Imprimés Traditionnels', 'tissus', 'Premium', 13000, array['img-tissus-2/wax sika imprimés traditionnels.jpg']::text[], 'Wax Sika Imprimés Traditionnels, un wax aux motifs sika, symboliques et colorés, transmis de génération en génération. Un classique toujours très demandé.', array['Motifs sika traditionnels', 'Couleurs symboliques', 'Rouleau de 6 yards', 'Tissage résistant']::text[], 14500, 4.8, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('parfum-exclusif')::uuid, 'Nos parfums exclusifs pour homme et femme 100 ml', 'parfums', 'Nouveau', 3000, array['img/produits/parfums-5.png']::text[], 'Nos parfums exclusifs pour homme et femme, 100 ml. Des fragrances raffinées aux notes orientales et boisées, longue tenue, pour une allure inoubliable en toutes occasions.', array['100 ml', 'Pour homme et femme', 'Tenue longue durée', 'Notes boisées et orientales']::text[], null, 4.8, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('hair-growth-faster-baume-capillaire')::uuid, 'Hair Growth Faster - Baume Capillaire Nourrissant & Anti-Pelliculaire', 'pommade', 'Populaire', 4500, array['img-capilaire/Hair Growth Faster - Baume Capillaire Nourrissant & Anti-Pelliculaire.jpg']::text[], 'Baume capillaire nourrissant et anti-pelliculaire qui favorise une pousse rapide et régulière. Enrichi en huiles natives et en actifs apaisants, il nourrit le cuir chevelu en profondeur, calme les irritations et redonne de l''éclat aux cheveux.', array['Nourrit et apaise le cuir chevelu', 'Anti-pelliculaire', 'Favorise la pousse', 'Huiles natives et actifs apaisants']::text[], 5500, 4.8, '2026-10-23T00:00:00+00:00'::timestamptz),
  (md5('gamme-de-savons-naturels-en-gomme-en-pate-verte')::uuid, 'Gamme de Savons Naturels - En Gomme & En Pâte Verte', 'divers', 'Nouveau', 3500, array['img-divers/Gamme de Savons Naturels - En Gomme & En Pâte Verte.jpg']::text[], 'Une gamme de savons 100 % naturels, disponible en gomme et en pâte, à la pâte verte. Formulés à l''huile végétale et à l''aloe vera, ils nettoient la peau en douceur, la protègent et respectent l''environnement.', array['100 % naturel', 'En gomme et en pâte verte', 'À l''huile végétale', 'Convient à tous les peaux']::text[], null, 4.7, '2026-10-23T00:00:00+00:00'::timestamptz)
